package com.nthexperience.desktop;
import android.app.Activity;
import android.content.Context;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.util.function.Consumer;

/** Ten notification cards and quick actions above the desktop. */
final class TenActionCenter {
 final Context context;final FrameLayout host;final DesktopStore store;final Consumer<String> open;FrameLayout overlay;LinearLayout panel,notices;boolean expanded;int safeLeft,safeRight,safeTop;final Runnable updated=this::renderNotices;boolean focusQuiet;
 final android.os.Handler focusHandler=new android.os.Handler(android.os.Looper.getMainLooper());final Runnable focusTick=new Runnable(){public void run(){if(overlay==null)return;boolean value=ElevenFocus.quiet(context);if(value!=focusQuiet)renderNotices();focusHandler.postDelayed(this,1000);}};
 TenActionCenter(Context c,FrameLayout host,DesktopStore store,Consumer<String> open){context=c;this.host=host;this.store=store;this.open=open;}
 boolean dismiss(){if(overlay==null)return false;focusHandler.removeCallbacks(focusTick);TenNotifications.unobserve(updated);host.removeView(overlay);overlay=null;notices=null;return true;}
 void safeInsets(int left,int right,int top){safeLeft=left;safeRight=right;safeTop=top;if(panel!=null&&overlay!=null){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)panel.getLayoutParams();int width=Math.min(dp(370),Math.max(1,host.getWidth()-left-right-dp(16))),height=Math.min(dp(680),Math.max(1,host.getHeight()-top-dp(16)));if(p.width!=width||p.height!=height||p.rightMargin!=right+dp(8)){p.width=width;p.height=height;p.rightMargin=right+dp(8);panel.setLayoutParams(p);}}}
 private int dp(int n){return Aero.dp(context,n);}
 void show(){
  dismiss();overlay=new FrameLayout(context);overlay.setElevation(dp(40));overlay.setContentDescription("Notifications and calendar overlay");overlay.setOnClickListener(v->dismiss());
  panel=Aero.column(context);panel.setPadding(dp(14),dp(10),dp(14),dp(12));panel.setBackground(ElevenMaterial.shell(context,8));panel.setOnClickListener(v->{});panel.setContentDescription("Notifications and calendar panel");
  int width=Math.min(dp(370),Math.max(1,host.getWidth()-safeLeft-safeRight-dp(16))),height=Math.min(dp(680),Math.max(1,host.getHeight()-safeTop-dp(16)));
  FrameLayout.LayoutParams bounds=new FrameLayout.LayoutParams(width,height,Gravity.BOTTOM|Gravity.END);bounds.rightMargin=safeRight+dp(8);bounds.bottomMargin=dp(8);overlay.addView(panel,bounds);
  LinearLayout header=new LinearLayout(context);TextView title=Aero.text(context,"Notifications",16,TenStyle.text(context));Aero.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));TextView close=TenStyle.command(context,"×",this::dismiss);close.setContentDescription("Close notifications and calendar");header.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));panel.addView(header);
  ScrollView scroll=new ScrollView(context);LinearLayout body=Aero.column(context);scroll.addView(body);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));notices=Aero.column(context);body.addView(notices);renderNotices();
  TextView date=Aero.text(context,new java.text.SimpleDateFormat("EEEE, MMMM d",java.util.Locale.getDefault()).format(new java.util.Date()),14,TenStyle.text(context));date.setPadding(0,dp(16),0,dp(10));body.addView(date);
  TextView month=Aero.text(context,"",14,TenStyle.text(context));month.setGravity(Gravity.CENTER);MonthCalendarView[] ref=new MonthCalendarView[1];MonthCalendarView calendar=new MonthCalendarView(context,()->{if(ref[0]!=null)month.setText(ref[0].title());});ref[0]=calendar;calendar.shellStyle();month.setText(calendar.title());
  LinearLayout nav=new LinearLayout(context);nav.addView(TenStyle.command(context,"‹",()->calendar.offset(-1)),new LinearLayout.LayoutParams(dp(48),dp(44)));nav.addView(month,new LinearLayout.LayoutParams(0,dp(44),1));nav.addView(TenStyle.command(context,"›",()->calendar.offset(1)),new LinearLayout.LayoutParams(dp(48),dp(44)));body.addView(nav);body.addView(calendar,new LinearLayout.LayoutParams(-1,dp(230)));body.addView(TenStyle.command(context,"Open Calendar",()->{dismiss();open.accept("@calendar");}));
  host.addView(overlay,new FrameLayout.LayoutParams(-1,-1));overlay.bringToFront();TenNotifications.observe(updated);focusHandler.removeCallbacks(focusTick);focusHandler.post(focusTick);
 }
 private void renderNotices(){if(notices==null)return;focusQuiet=ElevenFocus.quiet(context);notices.removeAllViews();java.util.List<ActionCenter.Alert> alerts=ActionCenter.alerts(context,store);java.util.List<TenNotifications.Row> apps=TenNotifications.rows(context);for(ActionCenter.Alert alert:alerts)card(alert.title,alert.message,()->{dismiss();open.accept(alert.target);},null);for(TenNotifications.Row row:apps)card(row.app+(!row.title.isEmpty()?" · "+row.title:""),row.text,()->{if(TenNotifications.open(row))dismiss();},row.dismissible?()->TenNotifications.dismiss(row.key):null);if(alerts.isEmpty()&&apps.isEmpty()){TextView empty=Aero.text(context,(store.prefs.getBoolean("ten_focus",false)||focusQuiet)?"Focus is on":"No new notifications",13,TenStyle.text(context));empty.setGravity(Gravity.CENTER);notices.addView(empty,new LinearLayout.LayoutParams(-1,dp(100)));}if(!TenNotifications.allowed(context)){TextView enable=TenStyle.command(context,"Show Android app notifications…",()->{dismiss();open.accept("ten-setting:notification-access");});enable.setTextSize(11);notices.addView(enable,new LinearLayout.LayoutParams(-1,dp(44)));}else if(!apps.isEmpty())notices.addView(TenStyle.command(context,"Clear all app notifications",TenNotifications::clear),new LinearLayout.LayoutParams(-1,dp(40)));}
 private void card(String title,String message,Runnable click,Runnable clear){LinearLayout card=Aero.column(context);card.setPadding(dp(10),dp(8),dp(10),dp(10));card.setBackgroundColor(TenStyle.light(context)?0xffe0e0e0:0xff303030);LinearLayout bar=new LinearLayout(context);TextView caption=Aero.text(context,title,12,TenStyle.text(context));caption.setMaxLines(2);bar.addView(caption,new LinearLayout.LayoutParams(0,dp(34),1));if(clear!=null){TextView x=TenStyle.command(context,"×",clear);x.setContentDescription("Dismiss "+title);bar.addView(x,new LinearLayout.LayoutParams(dp(36),dp(34)));}card.addView(bar);TextView text=Aero.text(context,message,12,TenStyle.text(context));text.setMaxLines(4);card.addView(text);card.setOnClickListener(v->click.run());card.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);notices.addView(card,p);}
}
